  private static Enumeration<Enumerations.ActorDefinitionActorType> convertActorDefinitionActorType(org.hl7.fhir.r5.model.Enumeration<org.hl7.fhir.r5.model.Enumerations.ExampleScenarioActorType> src) {
    if (src == null || src.isEmpty())
      return null;
    Enumeration<Enumerations.ActorDefinitionActorType> tgt = new Enumeration<Enumerations.ActorDefinitionActorType>(new Enumerations.ActorDefinitionActorTypeEnumFactory());
    ConversionContext50_N.INSTANCE.getVersionConvertor_50_N().copyElement(src, tgt);
    if (src.hasExtension("http://hl7.org/fhir/6.0/StructureDefinition/extension-ActorDefinition.type")) {
      tgt.setValue(Enumerations.ActorDefinitionActorType.fromCode(src.getExtensionString("http://hl7.org/fhir/6.0/StructureDefinition/extension-ActorDefinition.type")));
    } else {
      switch (src.getValue()) {
        case PERSON:
          tgt.setValue(Enumerations.ActorDefinitionActorType.PERSON);
          break;
        // conceptual is new in R6, and there is no useful mapping to R5
        case SYSTEM:
          tgt.setValue(Enumerations.ActorDefinitionActorType.SYSTEM);
          break;
        default:
          tgt.setValue(Enumerations.ActorDefinitionActorType.NULL);
          break;
      }
    }
    return tgt;
  }
